<span class="line">  <span class="token keyword">const</span> html <span class="token operator">=</span> editor<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">getHtml</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
