<span class="line">  <span class="token keyword">const</span> templates <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">sales</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">title</span><span class="token operator">:</span> <span class="token string">"销售合同模板"</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">content</span><span class="token operator">:</span> <span class="token string">"&lt;p>销售合同内容...&lt;/p>"</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">anchors</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
