<span class="line">    <span class="token literal-property property">service</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">title</span><span class="token operator">:</span> <span class="token string">"服务合同模板"</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">content</span><span class="token operator">:</span> <span class="token string">"&lt;p>服务合同内容...&lt;/p>"</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">anchors</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token comment">// 预定义的锚点数据</span></span>
