<span class="line">      <span class="token literal-property property">content</span><span class="token operator">:</span> <span class="token string">"&lt;p>租赁合同内容...&lt;/p>"</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">anchors</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token comment">// 预定义的锚点数据</span></span>
<span class="line">      <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">  <span class="token keyword">const</span> template <span class="token operator">=</span> templates<span class="token punctuation">[</span>templateName<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>template<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    contractTitle<span class="token punctuation">.</span>value <span class="token operator">=</span> template<span class="token punctuation">.</span>title<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>editor<span class="token punctuation">.</span>value<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
